"""Text templates embedded from the full Tobias Holzmann case."""

FILES = {
    '.color': "#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Updated on:  28 Oktober 2024                 #\n#----------------------------------------------#\n# Location:    www.Holzmann-cfd.de             #\n# Email:       Tobias.Holzmann@Holzmann-cfd.de #\n#----------------------------------------------#\n\n\n# Color definition for some bash highlight manipulation\n#------------------------------------------------------------------------------\nRED='\\e[0;31m'\nGREEN='\\e[0;32m'\nNC='\\e[0m'\nORANGE='\\033[0;33m'\nGRAY='\\e[0;37m'\nFL='\\033[0;36m'\n\n\n#------------------------------------------------------------------------------\n",
    '.preamble': '#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Updated on:  28 Oktober 2024                 #\n#----------------------------------------------#\n# Location:    https://Holzmann-cfd.com        #\n# Email:       community@Holzmann-cfd.com      #\n#----------------------------------------------#\n\n\n#------------------------------------------------------------------------------\n# Preamble with the information about the tutorial\necho -en "\n-------------------------------------------------------------------------------\n${GRAY}Tutorial by Tobias Holzmann${NC} :: Generated on July 2017\n${GRAY}Build for OpenFOAM version${NC}  :: OpenFOAM-12\n${GRAY}Tested on system${NC}            :: Ubuntu 24.04.1\n${GRAY}The case was updated on${NC}     :: 28 Oktober 2024\n-------------------------------------------------------------------------------\n\n\n${GREEN}Topic: Nothing special - droplets with nice velocity field${NC}\n-------------------------------------------------------------------------------\nThis case was done just for fun to proof some analytic calculation of\nmy colleague Christian Rodrigues. By the way Chris, if you ever use this case,\nthanks for the nice discussions in your office :)\\n\n-------------------------------------------------------------------------------\n\\n\n"\n\n\n#------------------------------------------------------------------------------\n# Check the OpenFOAM version\necho -e "   - Check OpenFOAM version. We need $foamVersion"\nuserFoamVersion=`echo "$WM_PROJECT-$WM_PROJECT_VERSION"`\n\nif [ "$userFoamVersion" == "$foamVersion" ]\nthen\n    echo -e  "   - ${GREEN}$foamVersion found...${NC}"\n\nelse\n    echo -e  "   - ${ORANGE}You are not using the correct OpenFOAM version"\n    echo -en "     Your version is $userFoamVersion and we need ${GREEN}"\n    echo -e  "$foamVersion${NC}\\n"\n\n    while true\n    do\n        echo -en  "   - Proceed with your OpenFOAM version (y/n): "\n        read proceed\n\n        if [ "$proceed" == "y" ]\n        then\n            break\n\n        elif [ "$proceed" == "n" ]\n        then\n            echo -e "\\n\\n"\n            exit\n\n        fi\n    done\nfi\n\n\n#------------------------------------------------------------------------------\n',
    '0.orig/U': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       volVectorField;\n    location    "0";\n    object      U;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 1 -1 0 0 0 0];\n\ninternalField   uniform (0 2.5 0);\n\nboundaryField\n{\n    symm1\n    {\n        type            symmetryPlane;\n    }\n\n    symm2\n    {\n        type            symmetryPlane;\n    }\n\n    inlet\n    {\n        type            fixedValue;\n        value           uniform (0 2.5 0);\n    }\n\n    outlet\n    {\n        type            pressureInletOutletVelocity;\n        value           uniform (0 0 0);\n    }\n\n    frontAndBack\n    {\n        type            empty;\n    }\n}\n\n\n// ************************************************************************* //\n',
    '0.orig/alpha.water': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       volScalarField;\n    object      alpha.water;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 0 0 0 0 0 0];\n\ninternalField   uniform 0;\n\nboundaryField\n{\n    symm1\n    {\n        type            symmetryPlane;\n    }\n\n    symm2\n    {\n        type            symmetryPlane;\n    }\n\n    inlet\n    {\n        type            zeroGradient;\n    }\n\n    outlet\n    {\n        type            inletOutlet;\n        inletValue      uniform 0;\n        value           uniform 0;\n    }\n\n    frontAndBack\n    {\n        type            empty;\n    }\n}\n\n// ************************************************************************* //\n',
    '0.orig/p_rgh': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       volScalarField;\n    object      p_rgh;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [1 -1 -2 0 0 0 0];\n\ninternalField   uniform 0;\n\nboundaryField\n{\n    symm1\n    {\n        type            symmetryPlane;\n    }\n\n    symm2\n    {\n        type            symmetryPlane;\n    }\n\n    inlet\n    {\n        type            fixedFluxPressure;\n        value           uniform 0;\n    }\n\n    outlet\n    {\n        type            totalPressure;\n        p0              uniform 0;\n    }\n\n    frontAndBack\n    {\n        type            empty;\n    }\n}\n\n// ************************************************************************* //\n',
    'clean': '#!/bin/bash\n#\n#----------------------------------------------#\n# Contributor: Tobias Holzmann                 #\n# Last Change: June 2017                       #\n# Email:       Tobias.Holzmann@Holzmann-cfd.de #\n# Location:    www.Holzmann-cfd.de             #\n#----------------------------------------------#\n\n\n#-------------------------------------------------------------------------------\ncd ${0%/*} || exit 1\nclear\n\n\n#-------------------------------------------------------------------------------\nfoamCleanTutorials\nrm -rf 0 log* constant/*/poly*\n\n\n#-------------------------------------------------------------------------------\n',
    'constant/g': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       uniformDimensionedVectorField;\n    location    "constant";\n    object      g;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndimensions      [0 1 -2 0 0 0 0];\nvalue           (0 -9.81 0);\n\n\n// ************************************************************************* //\n',
    'constant/momentumTransport': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "constant";\n    object      turbulenceProperties;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nsimulationType  laminar;\n\n\n// ************************************************************************* //\n',
    'constant/phaseProperties': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    format      ascii;\n    class       dictionary;\n    location    "constant";\n    object      phaseProperties;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nphases          ( water air );\n\nsigma           0.07;\n\n\n// ************************************************************************* //\n',
    'constant/physicalProperties.air': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    format      ascii;\n    class       dictionary;\n    location    "constant";\n    object      physicalProperties.air;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nviscosityModel  Newtonian;\n\nnu              1.48e-05;\n\nrho             1;\n\n\n// ************************************************************************* //\n',
    'constant/physicalProperties.water': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    format      ascii;\n    class       dictionary;\n    location    "constant";\n    object      physicalProperties.water;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nviscosityModel  Newtonian;\n\nnu              1e-06;\n\nrho             1000;\n\n\n// ************************************************************************* //\n',
    'constant/transportProperties': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "constant";\n    object      transportProperties;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nphases (water air);\n\nwater\n{\n    transportModel  Newtonian;\n    nu              1e-06;\n    rho             1000;\n}\n\nair\n{\n    transportModel  Newtonian;\n    nu              1.48e-05;\n    rho             1;\n}\n\nsigma            0.07;\n\n// ************************************************************************* //\n',
    'run': '#!/bin/bash\n#\n#-------------------------------------------------#\n# Contributor: Tobias Holzmann                    #\n# Updated on:  28 Oktober 2024                    #\n#-------------------------------------------------#\n# Topic:       Droplets                           #\n# OpenFOAM:    version 12 (Foundation)            #\n#-------------------------------------------------#\n# Website:     https://Holzmann-cfd.com           #\n# Email:       community@Holzmann-cfd.com         #\n#-------------------------------------------------#\n\n\n#------------------------------------------------------------------------------\nfoamVersion="OpenFOAM-12"\n\n\n#------------------------------------------------------------------------------\ncd ${0%/*} || exit 1\nclear\nsource clean\nsource .color\nsource .preamble\n\n\n#------------------------------------------------------------------------------\necho -e "\\n\nStart meshing\n-------------------------------------------------------------------------------\n"\n\n\n#------------------------------------------------------------------------------\necho -e "   - Create mesh"\nideasUnvToFoam cad/meshSquare.unv > logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Change the boundary types in the mesh"\nchangeDictionary >> logMeshing\n\n\n#------------------------------------------------------------------------------\necho -e "   - Copy 0.orig to 0 (because next step will make the folders)"\ncp -r 0.orig 0\n\n\n#------------------------------------------------------------------------------\necho -e "\\n\n-------------------------------------------------------------------------------\nEnd Meshing\\n\n"\n\n\n#------------------------------------------------------------------------------\nif [ `which interFoam` ]\nthen\n\n    #--------------------------------------------------------------------------\n    echo -e "   - Set the droplets"\n    setFields > logSolve\n\n\n    #--------------------------------------------------------------------------\n    echo -e "   - Start simulation (~ 35 minutes)"\n    foamRun >> logSolve\n\n\n    #--------------------------------------------------------------------------\nelse\n\n    #--------------------------------------------------------------------------\n    echo -en "   - Can not start simulation,"\n    echo -en " \'${RED}interFoam$NC\'"\n    echo -e " not available"\n\n\n    #--------------------------------------------------------------------------\nfi\n\n\n#------------------------------------------------------------------------------\necho -e "   - End\\n\\n"\n\n\n#------------------------------------------------------------------------------\n',
    'system/changeDictionaryDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    object      changeDictionaryDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nboundary\n{\n    symm1 \n    {\n        type    symmetryPlane;\n    }\n\n    symm2 \n    {\n        type    symmetryPlane;\n    }\n\n    frontAndBack \n    {\n        type    empty;\n    }\n}\n\n\n// ************************************************************************* //\n',
    'system/controlDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "system";\n    object      controlDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\napplication     foamRun;\n\nsolver          incompressibleVoF;\n\nstartFrom       startTime;\n\nstartTime       0;\n\nstopAt          endTime;\n\nendTime         0.12;\n\ndeltaT          0.00001;\n\nwriteControl    adjustableRunTime;\n\nwriteInterval   0.00025;\n\npurgeWrite      0;\n\nwriteFormat     ascii;\n\nwritePrecision  6;\n\nwriteCompression compressed;\n\ntimeFormat      general;\n\ntimePrecision   6;\n\nrunTimeModifiable yes;\n\nadjustTimeStep  yes;\n\nmaxCo           0.8;\n\nmaxAlphaCo      1;\n\nmaxDeltaT       1;\n\n\n// ************************************************************************* //\n',
    'system/fvSchemes': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "system";\n    object      fvSchemes;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nddtSchemes\n{\n    default         Euler;\n}\n\ngradSchemes\n{\n    default         Gauss linear;\n}\n\ndivSchemes\n{\n    div(rhoPhi,U)  Gauss linearUpwind grad(U);\n    div(phi,alpha)  Gauss vanLeer;\n    div(phirb,alpha) Gauss linear;\n    div(((rho*nuEff)*dev2(T(grad(U))))) Gauss linear;\n}\n\nlaplacianSchemes\n{\n    default         Gauss linear corrected;\n}\n\ninterpolationSchemes\n{\n    default         linear;\n}\n\nsnGradSchemes\n{\n    default         corrected;\n}\n\n\n// ************************************************************************* //\n',
    'system/fvSolution': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "system";\n    object      fvSolution;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\nsolvers\n{\n    "alpha.water.*"\n    {\n        nAlphaCorr      2;\n        nAlphaSubCycles 1;\n        cAlpha          1;\n\n        MULESCorr       yes;\n        nLimiterIter    5;\n\n        solver          smoothSolver;\n        smoother        symGaussSeidel;\n        tolerance       1e-8;\n        relTol          0;\n    }\n\n    "pcorr.*"\n    {\n        solver          PCG;\n        preconditioner  DIC;\n        tolerance       1e-5;\n        relTol          0;\n    }\n\n    p_rgh\n    {\n        solver           GAMG;\n        tolerance        5e-9;\n        relTol           0.01;\n\n        smoother         GaussSeidel;\n\n\n\n        maxIter          50;\n    }\n\n    p_rghFinal\n    {\n        $p_rgh;\n        relTol          0;\n    }\n\n    U\n    {\n        solver          smoothSolver;\n        smoother        symGaussSeidel;\n        tolerance       1e-06;\n        relTol          0;\n    }\n}\n\nPIMPLE\n{\n    momentumPredictor   no;\n    nOuterCorrectors    1;\n    nCorrectors         3;\n    nNonOrthogonalCorrectors 0;\n}\n\nrelaxationFactors\n{\n    equations\n    {\n        ".*" 1;\n    }\n}\n\n\n// ************************************************************************* //\n',
    'system/setFieldsDict': '/*--------------------------------*- C++ -*----------------------------------*\\\n| =========                 |                                                 |\n| \\\\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |\n|  \\\\    /   O peration     | Website:  www.openfoam.org                      |\n|   \\\\  /    A nd           | Version:  12                                    |\n|    \\\\/     M anipulation  |                                                 |\n\\*---------------------------------------------------------------------------*/\nFoamFile\n{\n    version     2.0;\n    format      ascii;\n    class       dictionary;\n    location    "system";\n    object      setFieldsDict;\n}\n// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //\n\ndefaultFieldValues\n(\n    volScalarFieldValue alpha.water 0\n    volVectorFieldValue U (0 2.5 0)\n);\n\nregions\n(\n    cylinderToCell\n    {\n        p1  (0.005 0.02 0);\n        p2  (0.005 0.02 1);\n        radius 0.0006;\n\n        fieldValues\n        (\n            volScalarFieldValue alpha.water 1\n            volVectorFieldValue U (0 0 0)\n        );\n    }\n\n    cylinderToCell\n    {\n        p1  (0.015 0.037 0);\n        p2  (0.015 0.037 1);\n        radius 0.001;\n\n        fieldValues\n        (\n            volScalarFieldValue alpha.water 1\n            volVectorFieldValue U (0 0 0)\n        );\n    }\n\n    cylinderToCell\n    {\n        p1  (0.022 0.015 0);\n        p2  (0.022 0.015 1);\n        radius 0.0003;\n\n        fieldValues\n        (\n            volScalarFieldValue alpha.water 1\n            volVectorFieldValue U (0 0 0)\n        );\n    }\n\n    cylinderToCell\n    {\n        p1  (0.032 0.03 0);\n        p2  (0.032 0.03 1);\n        radius 0.002;\n\n        fieldValues\n        (\n            volScalarFieldValue alpha.water 1\n            volVectorFieldValue U (0 0 0)\n        );\n    }\n);\n\n\n// ************************************************************************* //\n',
}
